import{_ as a,o as t,c as o,a6 as r}from"./chunks/framework.DHIwV8r3.js";const c=JSON.parse('{"title":"Rei Kawakubo","description":"","frontmatter":{},"headers":[],"relativePath":"designers/rei-kawakubo.md","filePath":"designers/rei-kawakubo.md","lastUpdated":1794245099000}'),i={name:"designers/rei-kawakubo.md"};function n(s,e,d,l,p,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="rei-kawakubo" tabindex="-1">Rei Kawakubo <a class="header-anchor" href="#rei-kawakubo" aria-label="Permalink to &quot;Rei Kawakubo&quot;">​</a></h1><p><strong>Study for:</strong> challenging conventions and building a distinctive point of view.</p><h2 id="brief-bio" tabindex="-1">Brief bio <a class="header-anchor" href="#brief-bio" aria-label="Permalink to &quot;Brief bio&quot;">​</a></h2><p>Rei Kawakubo is a Japanese designer and the founder of Comme des Garçons. Her work questions familiar boundaries between clothing, the body, and art. The Metropolitan Museum of Art devoted its 2017 exhibition, <em>Rei Kawakubo/Comme des Garçons: Art of the In-Between</em>, to that approach. <a href="https://www.metmuseum.org/exhibitions/listings/2017/rei-kawakubo" target="_blank" rel="noreferrer">The Met’s exhibition</a>.</p><p><strong><a href="https://www.gq.com/story/tommy-ton-rei-kawakubo-portrait" target="_blank" rel="noreferrer">View a portrait of Rei Kawakubo</a></strong> — Tommy Ton’s photograph accompanies GQ’s account of making the portrait. The photograph is linked at its source; no reuse license has been verified here.</p><h2 id="apply-it-to-our-white-tee" tabindex="-1">Apply it to our white tee <a class="header-anchor" href="#apply-it-to-our-white-tee" aria-label="Permalink to &quot;Apply it to our white tee&quot;">​</a></h2><ul><li><strong>Product:</strong> question one assumption—must a white tee be fitted, symmetrical, or styled as an undershirt?</li><li><strong>Website:</strong> test unexpected image crops or editorial compositions while keeping price, size, and buying controls clear.</li><li><strong>Brand:</strong> develop one recognizable idea instead of adding decoration everywhere.</li></ul><p>These are our proposed applications, not recommendations made by Kawakubo.</p><p><strong>Try this:</strong> make two mood boards for the same plain tee: quiet and experimental. Ask classmates what each suggests about the wearer and price.</p><p><a href="/white-tee-research/our-brand.html">← Our brand</a> · <a href="./jil-sander.html">Back to Jil Sander</a></p><p><em>Sources reviewed November 9, 2026.</em></p>',11)])])}const m=a(i,[["render",n]]);export{c as __pageData,m as default};
